examples.template:
VStack(alignment: .leading) {
    MonarchButton({{trigger}}, systemImage: "magnifyingglass") { isOpen = true }
        .keyboardShortcut("k", modifiers: .command)
        .sheet(isPresented: $isOpen) {
            NavigationStack {
                MonarchSearchResults(groups: matches, query: query) { command, _ in
                    lastCommand = command.title
                    isOpen = false
                }
                .searchable(text: $query, prompt: "Type a command or search")
                .navigationTitle("Command palette")
                #if os(iOS)
                .navigationBarTitleDisplayMode(.inline)
                #endif
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button("Close") { isOpen = false }
                    }
                }
            }
            .presentationDragIndicator(.visible)
            .onDisappear { query = "" }
        }
    Text(lastCommand.map { "Ran: " + $0 } ?? {{hint}})
}

examples.setupTemplate:
@State private var isOpen = false
@State private var query = ""
@State private var lastCommand: String?

private let commands = [
    MonarchSearchResultGroup(
        {{groups.0.title}},
        id: {{groups.0.id}},
        results: [
            MonarchSearchResult({{groups.0.items.0.label}}, id: {{groups.0.items.0.id}}, systemImage: "plus", meta: "C", tone: .neutral),
            MonarchSearchResult({{groups.0.items.1.label}}, id: {{groups.0.items.1.id}}, systemImage: "pencil", meta: "F2", tone: .neutral),
            MonarchSearchResult({{groups.0.items.2.label}}, id: {{groups.0.items.2.id}}, systemImage: "trash", tone: {{groups.0.items.2.tone|tone}}),
        ]
    ),
    MonarchSearchResultGroup(
        {{groups.1.title}},
        id: {{groups.1.id}},
        results: [
            MonarchSearchResult({{groups.1.items.0.label}}, id: {{groups.1.items.0.id}}, systemImage: "rectangle.split.3x1", meta: "G B", tone: .neutral),
            MonarchSearchResult({{groups.1.items.1.label}}, id: {{groups.1.items.1.id}}, systemImage: "list.bullet", meta: "G M", tone: .neutral),
            MonarchSearchResult({{groups.1.items.2.label}}, id: {{groups.1.items.2.id}}, snippet: {{groups.1.items.2.description}}, meta: "⌘,", tone: .neutral),
        ]
    ),
]

private var matches: [MonarchSearchResultGroup] {
    guard !query.isEmpty else { return commands }
    return commands.map { group in
        MonarchSearchResultGroup(
            group.title,
            id: group.id,
            results: group.results.filter { $0.title.localizedCaseInsensitiveContains(query) }
        )
    }
}

